<?php require_once '../config/auth.php';require_once '../config/database.php';require_once '../config/layout.php';require_role('hr');$lowongan=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT l.*,d.nama_divisi FROM lowongan l JOIN divisi d ON d.id_divisi=l.id_divisi WHERE l.id_lowongan=?');$s->execute([$lowongan]);$job=$s->fetch();if(!$job)die('Lowongan tidak ditemukan.');if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id_lamaran'];$hasil=$_POST['hasil'];$cat=trim($_POST['catatan']??'');$q=$pdo->prepare('SELECT la.*,la.id_tahapan_aktif,ts.urutan FROM lamaran la LEFT JOIN tahapan_seleksi ts ON ts.id_tahapan=la.id_tahapan_aktif WHERE la.id_lamaran=? AND la.id_lowongan=?');$q->execute([$id,$lowongan]);$la=$q->fetch();if($la && $la['status_lamaran']==='Diproses' && $la['id_tahapan_aktif']){$pdo->beginTransaction();$pdo->prepare('INSERT INTO hasil_seleksi(id_lamaran,id_tahapan,hasil,catatan) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE hasil=VALUES(hasil),catatan=VALUES(catatan),tanggal_seleksi=NOW()')->execute([$id,$la['id_tahapan_aktif'],$hasil,$cat]);if($hasil==='Tidak Lulus'){$pdo->prepare('UPDATE lamaran SET status_lamaran="Ditolak",id_tahapan_aktif=NULL WHERE id_lamaran=?')->execute([$id]);}else{$next=$pdo->prepare('SELECT id_tahapan FROM tahapan_seleksi WHERE id_lowongan=? AND urutan>? ORDER BY urutan LIMIT 1');$next->execute([$lowongan,$la['urutan']]);$n=$next->fetchColumn();if($n){$pdo->prepare('UPDATE lamaran SET id_tahapan_aktif=? WHERE id_lamaran=?')->execute([$n,$id]);}else{$pdo->prepare('UPDATE lamaran SET status_lamaran="Diterima",id_tahapan_aktif=NULL WHERE id_lamaran=?')->execute([$id]);}}$pdo->commit();flash('Hasil seleksi disimpan.');}header('Location: seleksi.php?id='.$lowongan);exit;}$q=$pdo->prepare('SELECT la.*,p.nama,p.email,ts.nama_tahapan,ts.urutan FROM lamaran la JOIN pelamar p ON p.id_pelamar=la.id_pelamar LEFT JOIN tahapan_seleksi ts ON ts.id_tahapan=la.id_tahapan_aktif WHERE la.id_lowongan=? ORDER BY la.id_lamaran DESC');$q->execute([$lowongan]);$apps=$q->fetchAll();page_header('Seleksi: '.$job['judul_lowongan']);?><div class="card"><h3>Tahapan</h3><ol><?php $st=$pdo->prepare('SELECT * FROM tahapan_seleksi WHERE id_lowongan=? ORDER BY urutan');$st->execute([$lowongan]);foreach($st as $x):?><li><?=e($x['nama_tahapan'])?> — <?=e($x['deskripsi'])?></li><?php endforeach;?></ol></div><table><tr><th>Pelamar</th><th>CV</th><th>Tahap Aktif</th><th>Status</th><th>Proses</th></tr><?php foreach($apps as $a):?><tr><td><strong><?=e($a['nama'])?></strong><br><?=e($a['email'])?></td><td><?php if(!empty($a['cv_path'])):?><a href="download_cv.php?id=<?=$a['id_lamaran']?>" target="_blank">Lihat CV</a><?php else:?>Tidak ada<?php endif;?></td><td><?=e($a['nama_tahapan']?:'-')?></td><td><?=e($a['status_lamaran'])?></td><td><?php if($a['status_lamaran']==='Diproses' && $a['id_tahapan_aktif']):?><form method="post"><input type="hidden" name="id_lamaran" value="<?=$a['id_lamaran']?>"><select name="hasil"><option value="Lulus">Lulus</option><option value="Tidak Lulus">Tidak Lulus</option></select><textarea name="catatan" placeholder="Catatan HR"></textarea><button class="btn">Simpan Hasil</button></form><?php else:?>Selesai<?php endif;?></td></tr><?php endforeach;?></table><?php page_footer();
